using System;using System.Linq;using System.Collections.Generic;using BeamScheduleFormatter;
class WorksSummaryLayoutTests {
 static void Main(){string[] cells={"5","6","9","10","11","14","15","16","19","20","21","22","23","24","25","26","27","30","31","32","34","35"};if(!WorksSummaryLayout.Map.Take(cells.Length).Select(m=>m[2]).SequenceEqual(cells))throw new Exception("Permanent summary cell contract moved");var values=new Dictionary<string,double>();int index=1;foreach(var m in WorksSummaryLayout.Map)values[m[0]]=index+++.125;var table=WorksSummaryLayout.Build(values);if(table.Name!="DTCE Tool Kit - POW"||table.Rows.GetLength(0)!=37)throw new Exception("Fixed sheet bounds changed");foreach(var m in WorksSummaryLayout.Map){int row=int.Parse(m[2])-2;if(Convert.ToDouble(table.Rows[row,1])!=values[m[0]]||Convert.ToString(table.Rows[row,2])!=m[3])throw new Exception("Cell/unit mismatch: "+m[0]);}values["FutureMetric"]=999;var revised=WorksSummaryLayout.Build(values);for(int r=0;r<37;r++)for(int c=0;c<3;c++)if(!object.Equals(table.Rows[r,c],revised.Rows[r,c]))throw new Exception("New metric shifted fixed output");if(WorksSummaryLayout.CellMap().Rows.GetLength(0)!=64)throw new Exception("Cell map incomplete");if(FinishTypeCatalog.Names.Length!=21||FinishTypeCatalog.FirstRow!=36||FinishTypeCatalog.LastRow!=56)throw new Exception("Preset material cells changed");int catalogRow=36;foreach(var item in FinishTypeCatalog.Map())if((string)item[3]!="E"+catalogRow++)throw new Exception("Finish preset cell moved");Console.WriteLine("PASS: 20 permanent Excel cell addresses, units, bounded summary and stable layout with additional metrics.");}
}
